CREATE OR REPLACE FUNCTION public.no_private_birth_fields(payload jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT NOT jsonb_path_exists(payload, '$.**.keyvalue() ? (@.key == "lat" || @.key == "lon" || @.key == "latitude" || @.key == "timezone" || @.key == "city" || @.key == "country" || @.key == "place" || @.key == "day" || @.key == "month" || @.key == "year" || @.key == "hour" || @.key == "minute" || @.key == "birthDate" || @.key == "birthTime" || @.key == "birthPlace")') AND NOT (payload ? 'longitude') $$;